/**
 * RAD-264: an agent's suggestions and comments made over MCP show up in an open editor without
 * a reload, attributed to the agent, and the author's typing is kept. The fixture holds a real
 * manuscript load and the real updates the MCP `suggest_edit` and `add_comment` tools stored
 * (generated by src-tauri/tests/live_updates.rs; synthetic text).
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { flushPromises, mount } from '@vue/test-utils';
import ManuscriptEditor from './ManuscriptEditor.vue';
import { followUpdates, LIVE_POLL_MS, sessionFromStored } from './manuscript-session';
import type { StoredManuscript, UpdatesSince } from './backend';

const fixture = JSON.parse(
  readFileSync(resolve(__dirname, '../../../fixtures/mcp/live-agent-updates.json'), 'utf8'),
) as { stored: StoredManuscript; live: UpdatesSince };

/** A poll that hands out the agent's updates once, then nothing new. */
function agentPoll() {
  let served = false;
  return vi.fn(async (after: number): Promise<UpdatesSince> => {
    if (!served && after < fixture.live.cursor) {
      served = true;
      return fixture.live;
    }
    return { cursor: Math.max(after, fixture.live.cursor), updates: [] };
  });
}

afterEach(() => vi.useRealTimers());

describe('live agent updates (RAD-264)', () => {
  it('shows an MCP suggest_edit and add_comment in the open editor, keeping typed text', async () => {
    vi.useFakeTimers({ shouldAdvanceTime: true });
    const save = vi.fn(async () => {});
    const poll = agentPoll();
    const session = sessionFromStored(
      fixture.stored,
      null,
      { save, debounceMs: 10 },
      undefined,
      poll,
    );
    const doc = session.sections.get(fixture.stored.sections[0]!.docId)!;
    const w = mount(ManuscriptEditor, { props: { doc }, attachTo: document.body });
    await flushPromises();
    await vi.advanceTimersByTimeAsync(0);
    const page = () => w.find('.tiptap');
    expect(page().find('ins.suggestion-insert').exists()).toBe(false);

    // The author types in the body while the agent is working.
    const editor = (
      w.vm as unknown as {
        $: {
          setupState: { editor: { commands: { insertContentAt: (p: number, t: string) => void } } };
        };
      }
    ).$.setupState.editor;
    expect(page().text()).toContain('The lantern flickered twice.');
    editor.commands.insertContentAt(page().text().indexOf('The') + 2, 'Late. ');

    await vi.advanceTimersByTimeAsync(LIVE_POLL_MS + 10);
    await flushPromises();
    expect(poll).toHaveBeenCalledWith(fixture.stored.updatesCursor);
    expect(page().find('ins.suggestion-insert').text()).toBe('guttered');
    expect(page().find('del.suggestion-delete').text()).toBe('flickered');
    expect(page().find('.comment-anchor').text()).toBe('lantern');
    expect(page().text()).toContain('Late. ');
    const items = w.findAll('[data-test="review-item"]').map((i) => i.text());
    expect(items.some((t) => t.includes('Insert') && t.includes('agent:'))).toBe(true);
    expect(items.some((t) => t.includes('Comment'))).toBe(true);

    // Only the author's own edit is saved; the agent's stored updates are not written back.
    await vi.advanceTimersByTimeAsync(100);
    await session.flush();
    const saved = save.mock.calls as unknown as [string, Uint8Array][];
    expect(saved.length).toBeGreaterThan(0);
    for (const [, update] of saved) expect(update.length).toBeLessThan(200);

    await session.close();
    const calls = poll.mock.calls.length;
    await vi.advanceTimersByTimeAsync(LIVE_POLL_MS * 4);
    expect(poll.mock.calls.length).toBe(calls); // stops on close
    w.unmount();
  });

  it('retries a failed poll from the same cursor and ignores unknown docs', async () => {
    vi.useFakeTimers();
    const docs = new Map();
    const poll = vi
      .fn()
      .mockRejectedValueOnce(new Error('database is locked'))
      .mockResolvedValue({ cursor: 9, updates: [{ docId: 'not-open', update: [0, 0] }] });
    const stop = followUpdates(docs, 3, poll, 100);
    await vi.advanceTimersByTimeAsync(100);
    await vi.advanceTimersByTimeAsync(100);
    expect(poll.mock.calls.slice(0, 2)).toEqual([[3], [3]]);
    await vi.advanceTimersByTimeAsync(100);
    expect(poll).toHaveBeenLastCalledWith(9);
    stop();
  });
});
